WITH matched_keys AS (SELECT id FROM orders EXCEPT SELECT id FROM orders WHERE channel IN ('partner', 'store')), kept_rows AS (SELECT s.* FROM orders s INNER JOIN matched_keys k ON s.id = k.id) SELECT customer_id, DATE_TRUNC('WEEK', order_date) AS week_start, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, SUM(CASE WHEN channel = 'mobile' THEN shipping_fee ELSE 0 END) AS mobile_shipping_fee, SORT_ARRAY(COLLECT_SET(status)) AS status_list, APPROX_PERCENTILE(shipping_fee, 0.95) AS shipping_fee_p95, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, COUNT(*) FILTER (WHERE status = 'SHIPPED') AS shipped_rows FROM kept_rows GROUP BY GROUPING SETS ((customer_id, DATE_TRUNC('WEEK', order_date)), (customer_id), ());
